import sys
import json
import re
import os

def evaluate_expression(expr, variables):
    try:
        # Replace variable names with their values
        for var, val in variables.items():
            expr = expr.replace(var, str(val))
        # Evaluate the expression safely
        result = eval(expr, {'__builtins__': None}, {})
        if isinstance(result, int):
            return result
        else:
            raise ValueError("Expression did not evaluate to an integer")
    except Exception as e:
        raise ValueError("expression did not evaluate to an integer")

def render_template_line(line, variables, line_number):
    errors_logged = False
    for match in re.finditer(r'\{\{([^}]*)\}\}', line):
        if errors_logged:
            break
        placeholder = match.group(1).strip()
        if not placeholder:
            continue
        if placeholder.startswith('='):
            expr = placeholder[1:]
            try:
                value = evaluate_expression(expr, variables)
                line = line.replace(f'{{{{{placeholder}}}}}', str(value))
            except ValueError as e:
                with open('errors.log', 'a') as f:
                    f.write(f"Line {line_number}: {line} | {str(e)}\n")
                errors_logged = True
        else:
            var = placeholder
            if var in variables:
                line = line.replace(f'{{{{{placeholder}}}}}', str(variables[var]))
            else:
                with open('errors.log', 'a') as f:
                    f.write(f"Line {line_number}: {line} | missing variable {var}\n")
                errors_logged = True
    return line

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_templates.py TEMPLATE_PATH JSON_PATH")
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        with open(json_path, 'r') as f:
            variables = json.load(f)
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON in {json_path}")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading JSON: {e}")
        sys.exit(1)

    try:
        with open(template_path, 'r') as f:
            lines = f.readlines()
    except IOError as e:
        print(f"Error reading template file: {e}")
        sys.exit(1)

    for line_number, line in enumerate(lines, 1):
        rendered_line = render_template_line(line.strip(), variables, line_number)
        if rendered_line:
            print(rendered_line)

if __name__ == "__main__":
    main()

import sys
import json
import re
from typing import Dict, List, Tuple, Optional

def evaluate_expression(expr: str, variables: Dict[str, int]) -> Optional[int]:
    try:
        # Replace variable names with their values
        for var, val in variables.items():
            expr = expr.replace(var, str(val))
        # Evaluate the expression safely
        result = eval(expr, {'__builtins__': None}, {})
        return int(result) if isinstance(result, int) else None
    except Exception:
        return None

def process_template_line(line: str, variables: Dict[str, int], line_num: int) -> Optional[str]:
    def replace_placeholder(match: re.Match) -> Optional[str]:
        placeholder = match.group(1)
        if '=' not in placeholder:
            return None
        expr_part = placeholder.split('=', 1)[1].strip()
        if not expr_part:
            return None
        result = evaluate_expression(expr_part, variables)
        if result is None:
            return None
        return str(result)

    # Find all placeholders in the line
    placeholders = re.findall(r'\{\{(.*?)\}\}', line)
    if not placeholders:
        return line

    # Try to replace each placeholder in order
    for placeholder in placeholders:
        result = replace_placeholder(placeholder)
        if result is None:
            return None
        line = line.replace(f'{{{{{placeholder}}}}}', result)

    return line

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_templates.py TEMPLATE_PATH JSON_PATH")
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        with open(json_path, 'r') as f:
            variables = json.load(f)
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON in {json_path}")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading JSON: {e}")
        sys.exit(1)

    errors_log = open('errors.log', 'w')
    try:
        with open(template_path, 'r') as f:
            lines = f.readlines()
    except IOError as e:
        print(f"Error reading template file: {e}")
        sys.exit(1)

    for line_num, line in enumerate(lines, 1):
        stripped_line = line.strip()
        if not stripped_line:
            continue
        processed_line = process_template_line(stripped_line, variables, line_num)
        if processed_line is not None:
            print(processed_line)
        else:
            errors_log.write(f"Line {line_num}: {line.strip()} | missing variable {re.search(r'\{\{(.*?)\}', line).group(1).split('=', 1)[0].strip()} or expression did not evaluate to an integer\n")

    errors_log.close()

if __name__ == "__main__":
    main()

import json
import sys
import re

def render_templates():
    if len(sys.argv) != 3:
        print("Usage: python render_templates.py TEMPLATE_PATH JSON_PATH")
        return

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        with open(json_path, 'r') as f:
            variables = json.load(f)
    except Exception as e:
        print(f"Error reading JSON file: {e}")
        return

    errors_log = open('errors.log', 'w')

    try:
        with open(template_path, 'r') as f:
            lines = f.readlines()
    except Exception as e:
        print(f"Error reading template file: {e}")
        return

    for line_num, line in enumerate(lines, 1):
        line_text = line.strip()
        processed_line = line_text
        first_error = None

        for match in re.finditer(r'\{\{([^}]+)\}\}', line):
            expr = match.group(1).strip()
            try:
                # Evaluate the expression safely
                try:
                    result = eval(expr, {'__builtins__': None}, {k: v for k, v in variables.items()})
                except NameError as e:
                    error_msg = f"missing variable {expr}"
                    if first_error is None:
                        first_error = (line_num, line_text, error_msg)
                    continue
                except Exception as e:
                    error_msg = f"expression did not evaluate to an integer"
                    if first_error is None:
                        first_error = (line_num, line_text, error_msg)
                    continue

                if not isinstance(result, int):
                    error_msg = f"expression did not evaluate to an integer"
                    if first_error is None:
                        first_error = (line_num, line_text, error_msg)
                    continue

                processed_line = processed_line.replace(match.group(0), str(result))
            except Exception:
                continue

        if first_error is not None:
            errors_log.write(f"Line {first_error[0]}: {first_error[1]} | {first_error[2]}\n")
            continue

        print(processed_line)

    errors_log.close()

if __name__ == "__main__":
    render_templates()
